def _get_token_usage(response) -> dict | None:
    """从大模型响应中提取 token 使用量。返回 {'input': int, 'output': int, 'total': int} 或 None。"""
    if response is None:
        return None
    usage = None
    if hasattr(response, "usage_metadata") and response.usage_metadata:
        usage = response.usage_metadata
    elif hasattr(response, "response_metadata") and response.response_metadata:
        meta = response.response_metadata
        usage = meta.get("usage") or meta.get("token_usage") or meta
    if not usage or not isinstance(usage, dict):
        return None
    # 兼容多种字段名
    inp = usage.get("input_tokens") or usage.get("prompt_tokens") or 0
    out = usage.get("output_tokens") or usage.get("completion_tokens") or 0
    if inp == 0 and out == 0:
        return None
    return {"input": inp, "output": out, "total": inp + out}


async def _single_ping(model, message: str, call_index: int):
    """单次请求，返回 (call_index, success, response_or_error, elapsed, token_usage)"""
    start = time.perf_counter()
    try:
        response = await model.ainvoke([{"role": "user", "content": message}])
        elapsed = time.perf_counter() - start
        token_usage = _get_token_usage(response)
        return (call_index, True, response, elapsed, token_usage)
    except Exception as e:
        elapsed = time.perf_counter() - start
        return (call_index, False, str(e), elapsed, None)

async def quick_ping_model(model_id: str = "model_for_content_generation", batch_size: int = 1, test_message: str = "你好"):
    """
    快速ping测试大模型响应，支持并发多请求以测试吞吐。

    Args:
        model_id: 模型ID
        batch_size: 并发请求数，默认 1。每个请求使用相同 test_message 但带唯一前缀以避免 KV cache 复用。
        test_message: 发送给模型的测试内容，默认 "你好"。
    """
    print(f"🚀 开始测试模型: {model_id}，并发数: {batch_size}")
    start_time = time.time()

    try:
        factory = ChatModelFactory()
        model = factory.create_langchain_model(model_id)

        # 为每次调用生成带唯一前缀的消息，避免 KV cache 复用
        tasks = []
        for i in range(batch_size):
            prefix = f"[调用{i}][{random.randint(0, 999999)}]"
            msg = f"{prefix}\n{test_message}"
            tasks.append(_single_ping(model, msg, i))

        print(f"📤 发送 {batch_size} 个并发测试请求（相同内容+唯一前缀）")
        print(f"📤 测试使用的大模型：{model_id}")
        results = await asyncio.gather(*tasks, return_exceptions=False)

        end_time = time.time()
        elapsed_total = end_time - start_time
        success_count = sum(1 for r in results if r[1])

        print(f"✅ 完成: {success_count}/{batch_size} 成功，总耗时: {elapsed_total:.2f}秒")
        for call_index, ok, resp_or_err, elapsed, token_usage in results:
            status = "✅" if ok else "❌"
            preview = ""
            if ok and hasattr(resp_or_err, "content"):
                preview = resp_or_err.content[:200].replace("\n", " ")
            elif not ok:
                preview = str(resp_or_err)[:200]
            token_str = ""
            if token_usage:
                token_str = f" | token: 入={token_usage['input']} 出={token_usage['output']} 总={token_usage['total']}"
            print(f"  {status} 调用{call_index}: {elapsed:.2f}s{token_str}\n结果预览: {preview}")

        return success_count == batch_size

    except Exception as e:
        print(f"❌ 发生错误: {e}")
        import traceback
        traceback.print_exc()
        return False

# 测试主模型
def _parse_args():
    p = argparse.ArgumentParser(description="LLM 快速 ping 测试")
    p.add_argument("--model_id", type=str, default="model_bailian_80b", help="模型 ID")
    p.add_argument("--batch_size", type=int, default=1, help="并发请求数，不传则默认 1")
    p.add_argument("--test_message", type=str, default=None, help="测试消息内容，不传则默认使用下方 instruction+input")
    return p.parse_args()


